// @RestController
class UsuarioController {
    private UsuarioService usuarioService = new UsuarioService();

    // Implementa el método para agregar un usuario
    public void agregarUsuario(Usuario usuario) {
        usuarioService.agregarUsuario(usuario);
    }

    // Implementa el método para obtener todos los usuarios
    public List<Usuario> obtenerUsuarios() {
        return usuarioService.obtenerUsuarios();
    }

    public static void main(String[] args) {
        UsuarioController controller = new UsuarioController();
        // Agregar un usuario de ejemplo
        Usuario usuario = new Usuario("Juan", "juan@example.com");
        controller.agregarUsuario(usuario);

        // Obtener y imprimir todos los usuarios
        List<Usuario> usuarios = controller.obtenerUsuarios();
        for (Usuario u : usuarios) {
            System.out.println(u.getNombre() + " - " + u.getEmail());
        }
    }
}
